CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own role" ON public.user_roles FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated;
CREATE TABLE public.conference_content (slug text PRIMARY KEY, document jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.conference_content TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.conference_content TO authenticated;
GRANT ALL ON public.conference_content TO service_role;
ALTER TABLE public.conference_content ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public event content" ON public.conference_content FOR SELECT TO anon, authenticated USING (slug = 'lome-2027');
CREATE POLICY "Admin insert" ON public.conference_content FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(), 'admin') AND slug = 'lome-2027');
CREATE POLICY "Admin update" ON public.conference_content FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin') AND slug = 'lome-2027') WITH CHECK (public.has_role(auth.uid(), 'admin') AND slug = 'lome-2027');
CREATE POLICY "Admin delete" ON public.conference_content FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'admin') AND slug = 'lome-2027');